export type PermKey = (typeof P)[keyof typeof P]

/** The scopable actions and the resource their scope ranges over (CONTRACTS §21). */
export const SCOPE_TYPE = {
  'account:read': 'account',
  'account:create': 'account',
  'account:update': 'account',
  'account:delete': 'account',
  'account:test': 'account',
  'account:credential:view': 'account',
  'proxy:read': 'proxy',
  'proxy:manage': 'proxy'
} as const

export type ScopableKey = keyof typeof SCOPE_TYPE

/** A scopable action with a scope: account:read:own, account:update:group/12, … */
export type ScopedPermKey = `${ScopableKey}:${string}`
/** A plugin permission: plugin.<plugin key>:<local key>. */
export type PluginPermKey = `plugin.${string}:${string}`
/** Any permission key the console names in code. */
export type PermRef = PermKey | ScopedPermKey | PluginPermKey

export interface PermMeta {
  module: string
  /** Flagged in the role editor: credentials, money, trust roots, code execution, identity. */
  sensitive: boolean
  /** Some of its routes need a step-up proof each time (CONTRACTS §80.2). */
  stepUp: boolean
  /** Soft dependencies, of the same scope for a scopable action; editor hints only. */
  requires: readonly PermKey[]
  description: { en: string; zh: string }
}

